python3 << 'PYEOF'
import json

with open('/tmp/report_data.json') as f:
    d = json.load(f)

kpis = d['kpis']
model_stats = d['model_stats']
cw_stats = d['cw_stats']
cond_stats = d['cond_stats']
chan_stats = d['chan_stats']
ts = d['ts']
monthly = d['monthly']
dist = d['dist']

# Helper: format numbers
def fmt_usd(v): return f"${v:,.2f}"
def fmt_pct(v): return f"{v:.1f}%"

# Build model table rows
model_rows = ""
for r in model_stats:
    badge_color = "#16a34a" if r['avg_margin'] > 0 else "#dc2626"
    model_rows += f"""
    <tr>
      <td class="fw-medium">{r['Shoe_Model']}</td>
      <td class="text-center">{int(r['count']):,}</td>
      <td class="text-right">${r['avg_retail']:.0f}</td>
      <td class="text-right">${r['avg_resale']:.0f}</td>
      <td class="text-right" style="color:{badge_color};font-weight:600">${r['avg_margin']:.2f}</td>
      <td class="text-right">{r['avg_days']:.1f}d</td>
      <td class="text-right">{r['pct_above']:.1f}%</td>
    </tr>"""

# Build colorway table rows (top 9)
cw_rows = ""
for r in cw_stats:
    badge_color = "#16a34a" if r['avg_margin'] > 0 else "#dc2626"
    cw_rows += f"""
    <tr>
      <td class="fw-medium">{r['Colorway']}</td>
      <td class="text-center">{int(r['count']):,}</td>
      <td class="text-right">${r['avg_resale']:.0f}</td>
      <td class="text-right" style="color:{badge_color};font-weight:600">${r['avg_margin']:.2f}</td>
      <td class="text-right">{r['avg_days']:.1f}d</td>
    </tr>"""

# Build channel table rows
chan_rows = ""
for r in chan_stats:
    badge_color = "#16a34a" if r['avg_margin'] > 0 else "#dc2626"
    fast_badge = '<span class="badge-fast">Fast</span>' if r['avg_days'] < 10 else '<span class="badge-slow">Slow</span>'
    chan_rows += f"""
    <tr>
      <td class="fw-medium">{r['Sales_Channel']}{fast_badge}</td>
      <td class="text-center">{int(r['count']):,}</td>
      <td class="text-right">${r['avg_resale']:.0f}</td>
      <td class="text-right" style="color:{badge_color};font-weight:600">${r['avg_margin']:.2f}</td>
      <td class="text-right"><strong>{r['avg_days']:.1f}d</strong></td>
      <td class="text-right">{r['pct_above']:.1f}%</td>
    </tr>"""

# Build condition table rows
cond_rows = ""
cond_colors = {'Deadstock (Brand New)': '#16a34a', 'VNDS (Very Near Deadstock)': '#ca8a04', 'Used': '#dc2626'}
for r in cond_stats:
    color = cond_colors.get(r['Condition'], '#374151')
    cond_rows += f"""
    <tr>
      <td class="fw-medium" style="color:{color}">{r['Condition']}</td>
      <td class="text-center">{int(r['count']):,}</td>
      <td class="text-right">${r['avg_retail']:.0f}</td>
      <td class="text-right">${r['avg_resale']:.0f}</td>
      <td class="text-right" style="color:{color};font-weight:600">${r['avg_margin']:.2f}</td>
      <td class="text-right">{r['avg_days']:.1f}d</td>
      <td class="text-right">{r['pct_above']:.1f}%</td>
    </tr>"""

# JSON for charts
ts_labels = json.dumps([r['YearMonth'] for r in ts])
ts_margin = json.dumps([round(r['avg_margin'],2) for r in ts])
ts_resale = json.dumps([round(r['avg_resale'],2) for r in ts])
ts_count = json.dumps([r['count'] for r in ts])
ts_days = json.dumps([round(r['avg_days'],2) for r in ts])

monthly_labels = json.dumps([r['month_name'] for r in monthly])
monthly_margin = json.dumps([round(r['avg_margin'],2) for r in monthly])
monthly_count = json.dumps([r['count'] for r in monthly])

dist_labels = json.dumps(dist['labels'])
dist_values = json.dumps(dist['values'])

model_names = json.dumps([r['Shoe_Model'] for r in model_stats])
model_margins = json.dumps([round(r['avg_margin'],2) for r in model_stats])
model_days = json.dumps([round(r['avg_days'],2) for r in model_stats])

chan_names = json.dumps([r['Sales_Channel'] for r in chan_stats])
chan_margins = json.dumps([round(r['avg_margin'],2) for r in chan_stats])
chan_days = json.dumps([round(r['avg_days'],2) for r in chan_stats])

cond_names = json.dumps([r['Condition'] for r in cond_stats])
cond_margins = json.dumps([round(r['avg_margin'],2) for r in cond_stats])
cond_resale = json.dumps([round(r['avg_resale'],2) for r in cond_stats])
cond_days = json.dumps([round(r['avg_days'],2) for r in cond_stats])

cw_names = json.dumps([r['Colorway'] for r in cw_stats])
cw_margins = json.dumps([round(r['avg_margin'],2) for r in cw_stats])

